using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options backed by a known source-generated context
var options = new JsonSerializerOptions();
options.TypeInfoResolverChain.Add(DemoContext.Default);

// 1) Strongly-typed retrieval: returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> typedInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Typed info for Person: {typedInfo.Type.Name}");

// 2) Probe without throwing — TryGetTypeInfo returns false if metadata isn't available
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? personInfo))
    Console.WriteLine($"Person metadata found: {personInfo!.Type.Name}");
else
    Console.WriteLine("Person metadata NOT found");

// Probe a type that is NOT in the context
if (options.TryGetTypeInfo(typeof(DateTime), out JsonTypeInfo? dtInfo))
    Console.WriteLine($"DateTime metadata found: {dtInfo!.Type.Name}");
else
    Console.WriteLine("DateTime metadata NOT found (expected)");

// Bonus: round-trip to prove it works
string json = JsonSerializer.Serialize(new Person("Ada", 37), typedInfo);
Person? p = JsonSerializer.Deserialize(json, typedInfo);
Console.WriteLine($"Round-trip: {p}");

// --- Types & context ---
public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class DemoContext : JsonSerializerContext;

